22: export async function openPGliteReplica(
23:   policy: StoragePolicy,
24:   storageKey: string,
25:   fetchImpl: typeof fetch = globalThis.fetch.bind(globalThis),
26: ): Promise<PGlite> {
27:   const dataDir = pgliteDataDir(policy, storageKey);
28:   if (dataDir) {
29:     return PGlite.create({
30:       dataDir,
31:       initialMemory: PGLITE_REPLICA_INITIAL_MEMORY,
32:       postgresqlconf: [...PGLITE_REPLICA_POSTGRESQL_CONF],
33:     });
34:   }
35: 
36:   const response = await fetchImpl(BASE_ARCHIVE);
37:   if (!response.ok) {
38:     throw new Error(`PGlite base archive failed: ${response.status} ${response.statusText}`);
39:   }
40:   return PGlite.create({
41:     loadDataDir: await response.blob(),
42:     initialMemory: PGLITE_REPLICA_INITIAL_MEMORY,
43:     postgresqlconf: [...PGLITE_REPLICA_POSTGRESQL_CONF],
44:   });
